    """
    for folder_cls in cls.WELLKNOWN_FOLDERS:
        localized_names = getattr(folder_cls, "LOCALIZED_NAMES", {})
        candidates = localized_names.get(locale, ())
        if folder_name.lower() in [c.lower() for c in candidates]:
            return folder_cls
    raise KeyError(
        "No folder class found for name %r and locale %r" % (folder_name, locale)
    )

